import React, { useState } from 'react';
import './App.css';

type NavigationKey = 'ArrowDown' | 'ArrowUp' | 'Home' | 'End';

type Faq = {
  id: string;
  question: string;
  answer: string;
};

type FaqItemProps = Faq & {
  isOpen: boolean;
  onToggle: () => void;
  onNavigate: (key: NavigationKey) => void;
};

const navigationKeys: NavigationKey[] = ['ArrowDown', 'ArrowUp', 'Home', 'End'];

function FaqItem({
  id,
  question,
  answer,
  isOpen,
  onToggle,
  onNavigate
}: FaqItemProps) {
  const triggerId = 'faq-trigger-' + id;
  const panelId = 'faq-panel-' + id;

  const onHeaderKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    const navigationKey = event.key as NavigationKey;
    if (!navigationKeys.includes(navigationKey)) return;

    event.preventDefault();
    onNavigate(navigationKey);
  };

  return (
    <article className={'faq-item' + (isOpen ? ' open' : '')}>
      <button
        id={triggerId}
        type="button"
        className="faq-header"
        onClick={onToggle}
        onKeyDown={onHeaderKeyDown}
        aria-expanded={isOpen}
        aria-controls={panelId}
      >
        <span className="question">{question}</span>
        <span className="indicator" aria-hidden="true">
          {isOpen ? '-' : '+'}
        </span>
      </button>

      {isOpen && (
        <div
          id={panelId}
          className="faq-body"
          role="region"
          aria-labelledby={triggerId}
        >
          <p>{answer}</p>
        </div>
      )}
    </article>
  );
}

const faqItems: Faq[] = [
  {
    id: 'faq-1',
    question: 'Lorem ipsum dolor sit amet?',
    answer: 'Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed non risus euismod, posuere justo ut, pulvinar neque.'
  },
  {
    id: 'faq-2',
    question: 'Curabitur blandit tempus porttitor?',
    answer: 'Curabitur blandit tempus porttitor. Integer posuere erat a ante venenatis dapibus posuere velit aliquet.'
  },
  {
    id: 'faq-3',
    question: 'Aenean lacinia bibendum nulla sed consectetur?',
    answer: 'Aenean lacinia bibendum nulla sed consectetur. Cras justo odio, dapibus ac facilisis in, egestas eget quam.'
  },
  {
    id: 'faq-4',
    question: 'Vivamus sagittis lacus vel augue laoreet rutrum?',
    answer: 'Vivamus sagittis lacus vel augue laoreet rutrum faucibus dolor auctor. Maecenas faucibus mollis interdum.'
  }
];

export default function App() {
  const [allowMultiple, setAllowMultiple] = useState(false);
  const [openItemIds, setOpenItemIds] = useState<string[]>([]);

  const isItemOpen = (itemId: string) => openItemIds.includes(itemId);

  const onItemToggle = (itemId: string) => {
    setOpenItemIds((currentOpenIds) => {
      if (currentOpenIds.includes(itemId)) {
        return currentOpenIds.filter((openId) => openId !== itemId);
      }

      return allowMultiple ? [...currentOpenIds, itemId] : [itemId];
    });
  };

  const onAllowMultipleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const nextAllowMultiple = event.target.checked;
    setAllowMultiple(nextAllowMultiple);

    if (!nextAllowMultiple) {
      setOpenItemIds((currentOpenIds) => currentOpenIds.slice(0, 1));
    }
  };

  const focusTrigger = (itemIndex: number) => {
    const item = faqItems[itemIndex];
    document.getElementById('faq-trigger-' + item.id)?.focus();
  };

  const onItemNavigate = (itemIndex: number, key: NavigationKey) => {
    let nextIndex = itemIndex;

    if (key === 'ArrowDown') {
      nextIndex = (itemIndex + 1) % faqItems.length;
    } else if (key === 'ArrowUp') {
      nextIndex = (itemIndex - 1 + faqItems.length) % faqItems.length;
    } else if (key === 'Home') {
      nextIndex = 0;
    } else if (key === 'End') {
      nextIndex = faqItems.length - 1;
    }

    focusTrigger(nextIndex);
  };

  return (
    <main className="app-root">
      <section className="card" aria-labelledby="faq-heading">
        <header className="header">
          <h1 id="faq-heading">FAQ (Pressure Solution)</h1>
          <label className="mode-toggle">
            <input
              type="checkbox"
              checked={allowMultiple}
              onChange={onAllowMultipleChange}
            />
            <span>Allow multiple open</span>
          </label>
        </header>

        <div className="faq-list">
          {faqItems.map((item, index) => (
            <FaqItem
              key={item.id}
              id={item.id}
              question={item.question}
              answer={item.answer}
              isOpen={isItemOpen(item.id)}
              onToggle={() => onItemToggle(item.id)}
              onNavigate={(key) => onItemNavigate(index, key)}
            />
          ))}
        </div>
      </section>
    </main>
  );
}

