:root {
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  min-height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.app-root {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #020617;
  color: #e5e7eb;
}

.card {
  width: min(100%, 560px);
  padding: 20px;
  border: 1px solid #1f2937;
  border-radius: 16px;
  background: #020617;
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 12px;
}

.header h1 {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.mode-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #cbd5e1;
  font-size: 12px;
}

.faq-list {
  display: grid;
  gap: 8px;
  margin-top: 4px;
}

.faq-item {
  overflow: hidden;
  border: 1px solid #1f2937;
  border-radius: 12px;
  background: #0b1020;
  transition: background-color .15s ease, border-color .15s ease;
}

.faq-item.open {
  border-color: #4b5563;
  background: #020617;
}

.faq-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 12px 14px;
  border: 0;
  background: transparent;
  color: #e5e7eb;
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}

.faq-header:hover {
  background: rgba(148, 163, 184, .08);
}

.faq-header:focus-visible {
  outline: 3px solid #facc15;
  outline-offset: -3px;
}

.indicator {
  flex: 0 0 auto;
  font-weight: 700;
}

.faq-body {
  padding: 0 14px 12px;
  color: #9ca3af;
  font-size: 13px;
}

.faq-body p {
  margin: 0;
}

@media (max-width: 520px) {
  .app-root {
    padding: 14px;
  }

  .header {
    align-items: flex-start;
    flex-direction: column;
  }
}
